class Solution:
    def getStrongest(self, arr: list[int], k: int) -> list[int]:
        arr.sort()
        n = len(arr)
        m = arr[(n - 1) // 2]
        left, right = 0, n - 1
        res = []
        for _ in range(k):
            if abs(arr[right] - m) >= abs(arr[left] - m):
                res.append(arr[right])
                right -= 1
            else:
                res.append(arr[left])
                left += 1
        return res

#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    std::vector<int> getStrongest(std::vector<int>& arr, int k) {
        std::sort(arr.begin(), arr.end());
        int n = arr.size();
        int m = arr[(n - 1) / 2];
        int left = 0, right = n - 1;
        std::vector<int> res;
        while ((int)res.size() < k) {
            if (std::abs(arr[right] - m) >= std::abs(arr[left] - m)) {
                res.push_back(arr[right--]);
            } else {
                res.push_back(arr[left++]);
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] getStrongest(int[] arr, int k) {
        Arrays.sort(arr);
        int n = arr.length;
        int m = arr[(n - 1) / 2];
        int left = 0, right = n - 1;
        int[] res = new int[k];
        for (int i = 0; i < k; i++) {
            if (Math.abs(arr[right] - m) >= Math.abs(arr[left] - m)) {
                res[i] = arr[right--];
            } else {
                res[i] = arr[left++];
            }
        }
        return res;
    }
}

var getStrongest = function(arr, k) {
    arr.sort((a, b) => a - b);
    const n = arr.length;
    const m = arr[Math.floor((n - 1) / 2)];
    let left = 0, right = n - 1;
    const res = [];
    while (res.length < k) {
        if (Math.abs(arr[right] - m) >= Math.abs(arr[left] - m)) {
            res.push(arr[right--]);
        } else {
            res.push(arr[left++]);
        }
    }
    return res;
};
